-- kestrel-agent-store-schema v1
-- A freshly booted Kestrel Core 0.63.0 agent database, without content.
-- Generated by tests/shared/agent_store_schema.py; do not edit by hand.
CREATE TABLE conversation_history (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    agent_id TEXT NOT NULL DEFAULT '',
    role TEXT NOT NULL,
    content TEXT NOT NULL,
    rendered_content TEXT DEFAULT NULL,
    model TEXT DEFAULT NULL,
    provider TEXT DEFAULT NULL,
    metadata TEXT,
    session_id TEXT DEFAULT NULL,
    lexical_index_id TEXT DEFAULT NULL,
    lexical_index_version TEXT DEFAULT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    deleted_at TIMESTAMP DEFAULT NULL,
    archived_at TIMESTAMP DEFAULT NULL, embedding_vec BLOB, embedding_profile_id TEXT,
    CONSTRAINT conversation_history_created_at_canonical CHECK (created_at IS NOT NULL AND created_at IS strftime('%Y-%m-%d %H:%M:%S', julianday(created_at)) AND created_at >= '0001-01-01 00:00:00')
);
CREATE TABLE files (
    content_hash TEXT PRIMARY KEY,
    original_name TEXT NOT NULL,
    content BLOB,
    metadata TEXT
);
CREATE TABLE file_owners (
    content_hash TEXT NOT NULL,
    agent_id TEXT NOT NULL,
    original_name TEXT NOT NULL,
    metadata TEXT,
    PRIMARY KEY (content_hash, agent_id)
);
CREATE TABLE graph_nodes (
    node_id TEXT PRIMARY KEY,
    node_type TEXT NOT NULL,
    label TEXT NOT NULL,
    properties TEXT
);
CREATE TABLE graph_edges (
    source_id TEXT NOT NULL,
    target_id TEXT NOT NULL,
    label TEXT NOT NULL,
    properties TEXT,
    PRIMARY KEY (source_id, target_id, label)
);
CREATE TABLE graph_node_owners (
    node_id TEXT NOT NULL,
    agent_id TEXT NOT NULL,
    PRIMARY KEY (node_id, agent_id)
);
CREATE TABLE graph_edge_owners (
    source_id TEXT NOT NULL,
    target_id TEXT NOT NULL,
    label TEXT NOT NULL,
    agent_id TEXT NOT NULL,
    PRIMARY KEY (source_id, target_id, label, agent_id)
);
CREATE TABLE document_chunks (
    chunk_id INTEGER PRIMARY KEY AUTOINCREMENT,
    file_hash TEXT NOT NULL,
    content TEXT NOT NULL,
    embedding_vec BLOB, embedding_profile_id TEXT);
CREATE TABLE document_chunk_owners (
    chunk_id INTEGER NOT NULL,
    agent_id TEXT NOT NULL,
    PRIMARY KEY (chunk_id, agent_id)
);
CREATE TABLE schema_backfills (
    name TEXT PRIMARY KEY,
    completed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE conversation_lexical_tokens (
    agent_id TEXT NOT NULL,
    lexical_index_id TEXT NOT NULL,
    token_hash TEXT NOT NULL,
    PRIMARY KEY (agent_id, lexical_index_id, token_hash)
);
CREATE TABLE conversation_titles (
    agent_id   TEXT NOT NULL,
    session_id TEXT NOT NULL,
    name       TEXT,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (agent_id, session_id)
);
CREATE TABLE model_usage (
    model_id TEXT PRIMARY KEY,
    provider TEXT NOT NULL,
    last_used TIMESTAMP NOT NULL,
    use_count INTEGER DEFAULT 0,
    total_tokens INTEGER DEFAULT 0,
    cache_creation_input_tokens BIGINT NOT NULL DEFAULT 0,
    cache_read_input_tokens BIGINT NOT NULL DEFAULT 0,
    cache_creation_input_tokens_report_count BIGINT NOT NULL DEFAULT 0,
    cache_read_input_tokens_report_count BIGINT NOT NULL DEFAULT 0,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE wallet_state (
    agent_id TEXT PRIMARY KEY,
    main_balance TEXT NOT NULL,
    audit_balance TEXT NOT NULL,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE wallet_transactions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    agent_id TEXT NOT NULL,
    transaction_type TEXT NOT NULL,
    currency TEXT NOT NULL DEFAULT 'FIL',
    amount TEXT NOT NULL,
    memo TEXT,
    new_balance TEXT NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE temporal_patterns (
    id TEXT PRIMARY KEY,
    agent_id TEXT NOT NULL,
    pattern_type TEXT NOT NULL,
    description TEXT NOT NULL,
    trigger_conditions TEXT,
    confidence REAL DEFAULT 0.0,
    observations INTEGER DEFAULT 0,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE memory_episodes (
    id TEXT PRIMARY KEY,
    agent_id TEXT NOT NULL,
    title TEXT NOT NULL,
    summary TEXT,
    timespan_start TIMESTAMP,
    timespan_end TIMESTAMP,
    key_message_ids TEXT,
    emotional_arc TEXT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
