    access_count INTEGER DEFAULT 0,
    embedding_vec BLOB,
    embedding_profile_id TEXT,
    excluded_from_context INTEGER DEFAULT 0
);
CREATE TABLE reflection_insights (
    id TEXT PRIMARY KEY,
    agent_id TEXT NOT NULL,
    session_id TEXT,
    type TEXT NOT NULL,
    title TEXT NOT NULL,
    description TEXT,
    evidence TEXT,
    confidence REAL DEFAULT 0.5,
