);
CREATE TABLE improvement_proposals (
    id TEXT PRIMARY KEY,
    agent_id TEXT NOT NULL,
    insight_id TEXT,
    title TEXT NOT NULL,
    description TEXT,
    change_type TEXT NOT NULL,
    proposed_change TEXT NOT NULL,
    requires_approval INTEGER DEFAULT 1,
    approved INTEGER DEFAULT 0,
    rejection_reason TEXT,
    approved_at TIMESTAMP,
    approved_by TEXT,
    applied_at TIMESTAMP,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE behavior_rules (
    id TEXT PRIMARY KEY,
    agent_id TEXT NOT NULL,
    proposal_id TEXT NOT NULL,
    trigger_condition TEXT NOT NULL,
    action TEXT NOT NULL,
    change_type TEXT NOT NULL,
    active INTEGER DEFAULT 1,
    priority INTEGER DEFAULT 0,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    deactivated_at TIMESTAMP
);
CREATE TABLE service_providers (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    supports_sub_accounts INTEGER DEFAULT 0,
    referral_program_url TEXT,
    api_docs_url TEXT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE user_service_keys (
    id TEXT PRIMARY KEY,
    user_id TEXT NOT NULL,
    provider_id TEXT NOT NULL,
    key_mode TEXT NOT NULL CHECK (key_mode IN ('byok', 'managed')),
    encrypted_key BLOB NOT NULL,
    key_hash TEXT NOT NULL,
    quota_limit INTEGER,
    quota_used INTEGER DEFAULT 0,
    referral_code TEXT,
    is_active INTEGER DEFAULT 1,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    expires_at TIMESTAMP,
    UNIQUE(user_id, provider_id)
);
CREATE TABLE agent_service_keys (
    id TEXT PRIMARY KEY,
    agent_did TEXT NOT NULL,
    provider_id TEXT NOT NULL,
    encrypted_key TEXT NOT NULL,
    key_hash TEXT NOT NULL,
    quota_limit INTEGER,
    quota_used INTEGER DEFAULT 0,
    is_active INTEGER DEFAULT 1,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    UNIQUE(agent_did, provider_id)
);
CREATE TABLE user_byok_service_keys (
    id TEXT PRIMARY KEY,
    agent_did TEXT NOT NULL,
    provider_id TEXT NOT NULL,
    encrypted_key TEXT NOT NULL,
    key_salt TEXT NOT NULL,
    key_nonce TEXT NOT NULL,
    key_hash TEXT NOT NULL,
    kdf TEXT NOT NULL DEFAULT 'PBKDF2-SHA256',
    kdf_iterations INTEGER NOT NULL DEFAULT 600000,
    is_active INTEGER DEFAULT 1,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    UNIQUE(agent_did, provider_id)
);
CREATE TABLE host_service_keys (
    id TEXT PRIMARY KEY,
    provider_id TEXT NOT NULL UNIQUE,
    encrypted_key TEXT NOT NULL,
    key_hash TEXT NOT NULL,
    is_active INTEGER DEFAULT 1,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE user_master_service_keys (
    id TEXT PRIMARY KEY,
    master_did TEXT NOT NULL,
    provider_id TEXT NOT NULL,
    encrypted_key TEXT NOT NULL,
    key_hash TEXT NOT NULL,
    is_active INTEGER DEFAULT 1,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    UNIQUE(master_did, provider_id)
);
CREATE TABLE sponsor_master_service_keys (
    id TEXT PRIMARY KEY,
    master_did TEXT NOT NULL,
    provider_id TEXT NOT NULL,
    encrypted_key TEXT NOT NULL,
    key_hash TEXT NOT NULL,
    is_active INTEGER DEFAULT 1,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    UNIQUE(master_did, provider_id)
);
CREATE TABLE sponsor_beneficiaries (
    sponsor_did TEXT NOT NULL,
    agent_did TEXT NOT NULL,
    is_active INTEGER DEFAULT 1,
    enrolled_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (agent_did)
);
CREATE TABLE service_key_usage (
    id TEXT PRIMARY KEY,
    key_id TEXT NOT NULL,
    key_type TEXT NOT NULL CHECK (key_type IN ('user', 'agent', 'companion')),
    provider_id TEXT NOT NULL,
    operation TEXT NOT NULL,
    units_consumed INTEGER DEFAULT 1,
    cost_estimate_usd REAL,
    companion_id TEXT,
    request_metadata TEXT,
    recorded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE agent_metadata (
    agent_id TEXT NOT NULL,
    key TEXT NOT NULL,
    value TEXT NOT NULL,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (agent_id, key)
);
CREATE TABLE agent_identity_resources (
    id TEXT PRIMARY KEY,
    agent_id TEXT NOT NULL,
    resource_id TEXT NOT NULL,
    resource_type TEXT NOT NULL,
    version INTEGER NOT NULL,
    is_current INTEGER DEFAULT 0,
    content_ciphertext BLOB NOT NULL,
    content_hash TEXT NOT NULL,
    content_bytes INTEGER NOT NULL,
    encryption TEXT NOT NULL,
    provenance TEXT,
    public_metadata TEXT,
    anchoring_metadata TEXT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    UNIQUE(agent_id, resource_type, version)
);
CREATE TABLE bootstrap_config (
    id TEXT PRIMARY KEY,
    agent_id TEXT NOT NULL,
    file_name TEXT NOT NULL,
    file_path TEXT DEFAULT '',
    enabled INTEGER DEFAULT 1,
    priority INTEGER DEFAULT 100,
    max_size_bytes INTEGER DEFAULT 10240,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE saved_items (
    id TEXT PRIMARY KEY,
    agent_id TEXT NOT NULL,
    item_type TEXT NOT NULL,
    name TEXT NOT NULL,
    summary TEXT,
    content TEXT NOT NULL,
    content_hash TEXT,
    ipfs_cid TEXT,
    source_type TEXT,
    source_ref TEXT,
    schema_id TEXT,
    tags TEXT,
    metadata TEXT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
, embedding_vec BLOB, embedding_profile_id TEXT);
CREATE TABLE wait_signal_state (
    agent_id TEXT NOT NULL DEFAULT '',
    kind TEXT NOT NULL,
    handle TEXT NOT NULL,
    last_signaled_outcome TEXT,
    last_delivery_status TEXT,
    last_surface_status TEXT,
    last_delivery_error TEXT,
    last_delivery_attempts INTEGER NOT NULL DEFAULT 0,
    last_delivery_attempt_at TIMESTAMP,
    -- Attempts belong to a TRANSITION, not to a handle (#3105). A provider
    -- that corrects a terminal state (talon finished_unknown -> failed) starts
    -- a new transition whose first wake is news, not attempt N+1 of the old
    -- one. This records which signaled token the counter is counting.
    attempts_signaled_target TEXT NOT NULL DEFAULT '',
    -- When the current attempt was DISPATCHED. last_delivery_attempt_at is
    -- rewritten at harvest time, so it answers "when did we last look", not
    -- "when did we try" — a difference measured at 41 minutes live.
    last_attempt_started_at TIMESTAMP,
    -- A wake whose cognition could not run because the model provider named
    -- its own retry time (#3302) is parked until then instead of spending
    -- delivery attempts inside that window. NULL when nothing is parked.
    delivery_deferred_until TIMESTAMP,
    -- How many times this transition's wake was parked that way.
    delivery_deferrals INTEGER NOT NULL DEFAULT 0,
    -- The recorded attempt count a wake was locked at when it reached the
    -- retry cap (#3391), copied from last_delivery_attempts by the lock
    -- itself. NULL on every row that is not currently locked.
    delivery_locked_attempts INTEGER,
    pending_signal_id TEXT,
    pending_signaled_target TEXT,
    pending_signal_enqueued_at TIMESTAMP,
    watching INTEGER NOT NULL DEFAULT 0,
    watch_baseline TEXT,
    watch_origin_session_id TEXT,
    last_delivered_at TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (agent_id, kind, handle)
);
CREATE TABLE operator_notice_audit (
    id TEXT PRIMARY KEY,
    notice_id TEXT NOT NULL,
    agent_id TEXT NOT NULL DEFAULT '',
    session_id TEXT,
    source TEXT NOT NULL,
    event_index INTEGER NOT NULL DEFAULT 0,
    delivery_role TEXT NOT NULL,
    fallback INTEGER NOT NULL DEFAULT 0,
    route TEXT NOT NULL DEFAULT '',
    payload TEXT,
    state TEXT NOT NULL DEFAULT 'collected' CHECK (
        state IN ('collected', 'injected', 'delivered', 'failed', 'cancelled')
    ),
    state_reason TEXT NOT NULL DEFAULT '',
    durable_trace INTEGER NOT NULL DEFAULT 0,
    requeued INTEGER NOT NULL DEFAULT 0,
    collected_at TIMESTAMP NOT NULL,
    injected_at TIMESTAMP,
    settled_at TIMESTAMP,
    retention_until TIMESTAMP NOT NULL
);
CREATE TABLE model_usage_periods (
    period_start TIMESTAMP NOT NULL,
    model_id TEXT NOT NULL,
    provider TEXT NOT NULL,
    use_count INTEGER NOT NULL DEFAULT 0,
    total_tokens BIGINT NOT NULL DEFAULT 0,
    cache_creation_input_tokens BIGINT NOT NULL DEFAULT 0,
    cache_read_input_tokens BIGINT NOT NULL DEFAULT 0,
    cache_creation_input_tokens_report_count BIGINT NOT NULL DEFAULT 0,
    cache_read_input_tokens_report_count BIGINT NOT NULL DEFAULT 0,
    PRIMARY KEY (period_start, model_id, provider)
);
CREATE TABLE semantic_schema_migrations (version TEXT PRIMARY KEY, completed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE semantic_assertion_tenants (
            tenant_id TEXT PRIMARY KEY,
            generation INTEGER NOT NULL DEFAULT 0,
            updated_at TEXT NOT NULL
        );
CREATE TABLE semantic_assertions (
            tenant_id TEXT NOT NULL,
            assertion_id TEXT NOT NULL,
            owning_agent_id TEXT NOT NULL,
            current_revision_id TEXT NOT NULL,
            created_at TEXT NOT NULL,
            PRIMARY KEY (tenant_id, assertion_id)
        );
CREATE TABLE semantic_assertion_revisions (
            revision_id TEXT PRIMARY KEY,
            tenant_id TEXT NOT NULL,
            assertion_id TEXT NOT NULL,
            owning_agent_id TEXT NOT NULL,
            status TEXT NOT NULL,
            epistemic_state TEXT NOT NULL,
            subject_value TEXT NOT NULL,
            predicate_value TEXT NOT NULL,
            object_kind TEXT NOT NULL,
            object_value TEXT NOT NULL,
            object_datatype TEXT,
            object_language TEXT,
            asserted_at TEXT NOT NULL,
            observed_start TEXT,
            observed_end TEXT,
            valid_start TEXT,
            valid_end TEXT,
            supersedes_revision_id TEXT,
            lineage_kind TEXT NOT NULL,
            eligible INTEGER NOT NULL,
            accepted_order INTEGER NOT NULL,
            assertion_mapping TEXT NOT NULL,
            CHECK (status IN ('active', 'superseded', 'retracted', 'quarantined', 'deleted')),
            CHECK (epistemic_state IN ('asserted', 'observed', 'reported', 'inferred', 'hypothesis', 'disputed', 'retracted')),
            CHECK (lineage_kind IN ('direct', 'derived')),
            CHECK (eligible IN (0, 1)),
            CHECK (accepted_order > 0),
            CHECK ((status = 'retracted') = (epistemic_state = 'retracted')),
            CHECK (status NOT IN ('retracted', 'quarantined', 'deleted') OR supersedes_revision_id IS NULL),
            UNIQUE (tenant_id, assertion_id, revision_id)
        );
CREATE TABLE semantic_source_occurrences (
            tenant_id TEXT NOT NULL,
            source_occurrence_id TEXT NOT NULL,
            source_kind TEXT NOT NULL,
            locator TEXT NOT NULL,
            received_at TEXT NOT NULL,
            content_digest TEXT,
            actor TEXT,
            selector TEXT,
            source_mapping TEXT NOT NULL,
            PRIMARY KEY (tenant_id, source_occurrence_id)
        );
CREATE TABLE semantic_revision_sources (
            tenant_id TEXT NOT NULL,
            revision_id TEXT NOT NULL,
            source_occurrence_id TEXT NOT NULL,
            ordinal INTEGER NOT NULL,
            CHECK (ordinal >= 0),
            PRIMARY KEY (tenant_id, revision_id, source_occurrence_id),
            UNIQUE (tenant_id, revision_id, ordinal)
        );
CREATE TABLE semantic_derivation_inputs (
            tenant_id TEXT NOT NULL,
            derived_revision_id TEXT NOT NULL,
            input_revision_id TEXT NOT NULL,
            ordinal INTEGER NOT NULL,
            CHECK (ordinal >= 0),
            PRIMARY KEY (tenant_id, derived_revision_id, input_revision_id),
            UNIQUE (tenant_id, derived_revision_id, ordinal)
        );
CREATE TABLE semantic_inference_runs (
            tenant_id TEXT NOT NULL,
            run_id TEXT NOT NULL,
            profile_key TEXT NOT NULL,
            ontology_namespace TEXT NOT NULL,
            ontology_version TEXT NOT NULL,
            ontology_digest TEXT NOT NULL,
            source_generation INTEGER NOT NULL,
            status TEXT NOT NULL,
            incomplete_reason TEXT,
            result_mapping TEXT NOT NULL,
            started_at TEXT NOT NULL,
            completed_at TEXT,
            PRIMARY KEY (tenant_id, run_id),
            CHECK (source_generation >= 0),
            CHECK (status IN ('running', 'complete', 'incomplete', 'failed'))
        );
CREATE TABLE semantic_inference_state (
            tenant_id TEXT NOT NULL,
            profile_key TEXT NOT NULL,
            run_id TEXT NOT NULL,
            source_generation INTEGER NOT NULL,
            status TEXT NOT NULL,
            incomplete_reason TEXT,
            updated_at TEXT NOT NULL,
            PRIMARY KEY (tenant_id, profile_key),
            CHECK (source_generation >= 0),
            CHECK (status IN ('running', 'complete', 'incomplete', 'failed'))
        );
CREATE TABLE semantic_inference_derivations (
            tenant_id TEXT NOT NULL,
            derivation_id TEXT NOT NULL,
            derived_assertion_id TEXT NOT NULL,
            derived_revision_id TEXT NOT NULL,
            rule_id TEXT NOT NULL,
            profile_key TEXT NOT NULL,
            rule_profile_version TEXT NOT NULL,
            ontology_namespace TEXT NOT NULL,
            ontology_version TEXT NOT NULL,
            ontology_digest TEXT NOT NULL,
            run_id TEXT NOT NULL,
            generated_at TEXT NOT NULL,
            active INTEGER NOT NULL,
            PRIMARY KEY (tenant_id, derivation_id),
            CHECK (active IN (0, 1))
        );
CREATE TABLE semantic_inference_derivation_inputs (
            tenant_id TEXT NOT NULL,
            derivation_id TEXT NOT NULL,
            input_revision_id TEXT NOT NULL,
            ordinal INTEGER NOT NULL,
            PRIMARY KEY (tenant_id, derivation_id, input_revision_id),
            UNIQUE (tenant_id, derivation_id, ordinal),
            CHECK (ordinal >= 0)
        );
CREATE TABLE semantic_projection_eligibility (
            tenant_id TEXT NOT NULL,
            revision_id TEXT NOT NULL,
            eligible INTEGER NOT NULL,
            updated_at TEXT NOT NULL,
            CHECK (eligible IN (0, 1)),
            PRIMARY KEY (tenant_id, revision_id)
        );
CREATE TABLE semantic_projection_outbox (
            event_id TEXT PRIMARY KEY,
            tenant_id TEXT NOT NULL,
            assertion_id TEXT NOT NULL,
            revision_id TEXT NOT NULL,
            operation TEXT NOT NULL,
            generation INTEGER NOT NULL,
            eligible INTEGER NOT NULL,
            created_at TEXT NOT NULL,
            CHECK (eligible IN (0, 1)),
            CHECK (generation > 0)
        );
CREATE TABLE semantic_projection_erasure_outbox (
            event_id TEXT PRIMARY KEY,
            tenant_id TEXT NOT NULL,
            operation TEXT NOT NULL,
            generation INTEGER NOT NULL,
            created_at TEXT NOT NULL,
            CHECK (operation = 'erased'),
            CHECK (generation > 0)
        );
CREATE TABLE semantic_assertion_operations (
            tenant_id TEXT NOT NULL,
            operation_id TEXT NOT NULL,
            operation TEXT NOT NULL,
            request_digest TEXT NOT NULL,
            receipt TEXT NOT NULL,
            assertion_ids TEXT NOT NULL,
            revision_ids TEXT NOT NULL,
            created_at TEXT NOT NULL,
            PRIMARY KEY (tenant_id, operation_id)
        );
CREATE TABLE semantic_assertion_erasure_receipts (
            tenant_id TEXT NOT NULL,
            operation_id TEXT NOT NULL,
            request_digest TEXT NOT NULL,
            generation INTEGER NOT NULL,
            created_at TEXT NOT NULL,
            PRIMARY KEY (tenant_id, operation_id)
        );
CREATE TABLE semantic_assertion_erased_operation_tombstones (
            tenant_id TEXT NOT NULL,
            purpose TEXT NOT NULL,
            operation_key TEXT NOT NULL,
            request_key TEXT NOT NULL,
            generation INTEGER NOT NULL,
            created_at TEXT NOT NULL,
            PRIMARY KEY (tenant_id, purpose, operation_key),
            UNIQUE (tenant_id, operation_key),
            CHECK (generation > 0)
        );
CREATE TABLE semantic_assertion_legacy_erasure_fences (
            tenant_id TEXT NOT NULL,
            assertion_key TEXT NOT NULL,
            generation INTEGER NOT NULL,
            created_at TEXT NOT NULL,
            PRIMARY KEY (tenant_id, assertion_key),
            CHECK (generation > 0)
        );
CREATE TABLE semantic_assertion_vector_projection_entries (
            tenant_id TEXT NOT NULL,
            profile_id TEXT NOT NULL,
            capability_digest TEXT NOT NULL,
            embedding_provider TEXT NOT NULL,
            embedding_model TEXT NOT NULL,
            embedding_dimension INTEGER NOT NULL,
            renderer_version TEXT NOT NULL,
            embedding_destination TEXT NOT NULL,
            visibility_ceiling TEXT NOT NULL,
            privacy_ceiling TEXT NOT NULL,
            visibility TEXT NOT NULL,
            privacy_classification TEXT NOT NULL,
            assertion_id TEXT NOT NULL,
            revision_id TEXT NOT NULL,
            revision_digest TEXT NOT NULL,
            source_generation INTEGER NOT NULL,
            vector_json TEXT NOT NULL,
            created_at TEXT NOT NULL,
            PRIMARY KEY (tenant_id, profile_id, capability_digest, assertion_id),
            UNIQUE (tenant_id, profile_id, capability_digest, revision_id),
            CHECK (source_generation > 0),
            CHECK (embedding_dimension > 0 AND embedding_dimension <= 8192),
            CHECK (embedding_destination IN ('local', 'remote')),
            CHECK (visibility_ceiling IN ('private', 'tenant', 'delegated', 'public')),
            CHECK (visibility IN ('private', 'tenant', 'delegated', 'public'))
        );
CREATE TABLE semantic_assertion_vector_projection_state (
            tenant_id TEXT NOT NULL,
            profile_id TEXT NOT NULL,
            capability_digest TEXT NOT NULL,
            checkpoint_generation INTEGER NOT NULL,
            checkpoint_event_id TEXT,
            updated_at TEXT NOT NULL,
            PRIMARY KEY (tenant_id, profile_id, capability_digest),
            CHECK (checkpoint_generation >= 0)
        );
CREATE TABLE semantic_governed_artifacts (
            tenant_id TEXT NOT NULL,
            artifact_id TEXT NOT NULL,
            kind TEXT NOT NULL,
            consumer_id TEXT NOT NULL,
            consumer_key_id TEXT NOT NULL,
            consumer_public_key TEXT NOT NULL,
            checkpoint_generation INTEGER NOT NULL,
            policy_pin TEXT NOT NULL,
            capability_digest TEXT NOT NULL,
            artifact_digest TEXT,
            retention_expires_at TEXT NOT NULL,
            state TEXT NOT NULL,
            invalidated_generation INTEGER,
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL,
            PRIMARY KEY (tenant_id, artifact_id),
            CHECK (kind IN ('export_snapshot', 'corpus_manifest', 'future_corpus_candidate')),
            CHECK (state IN ('active', 'revocation_pending', 'revoked', 'expired')),
            CHECK (checkpoint_generation >= 0),
            CHECK (invalidated_generation IS NULL OR invalidated_generation >= 0)
        );
CREATE TABLE semantic_governed_artifact_lineage (
            tenant_id TEXT NOT NULL,
            artifact_id TEXT NOT NULL,
            assertion_id TEXT NOT NULL,
            revision_id TEXT NOT NULL,
            PRIMARY KEY (tenant_id, artifact_id, assertion_id, revision_id)
        );
CREATE TABLE semantic_governed_artifact_revocations (
            tenant_id TEXT NOT NULL,
            revocation_id TEXT NOT NULL,
            artifact_key TEXT NOT NULL,
            kind TEXT NOT NULL,
            consumer_id TEXT NOT NULL,
            consumer_key_id TEXT NOT NULL,
            consumer_public_key TEXT NOT NULL,
            artifact_digest TEXT,
            attempt INTEGER NOT NULL DEFAULT 0,
            lease_token TEXT,
            lease_expires_at TEXT,
            acknowledged_at TEXT,
            deletion_proof_digest TEXT,
            invalidated_generation INTEGER NOT NULL,
            PRIMARY KEY (tenant_id, revocation_id),
            CHECK (attempt >= 0),
            CHECK (kind IN ('export_snapshot', 'corpus_manifest', 'future_corpus_candidate')),
            CHECK (invalidated_generation >= 0)
        );
CREATE TABLE semantic_governed_artifact_receipts (
            receipt_id TEXT PRIMARY KEY,
            tenant_id TEXT NOT NULL,
            artifact_key TEXT NOT NULL,
            kind TEXT NOT NULL,
            state TEXT NOT NULL,
            generation INTEGER NOT NULL,
            receipt_digest TEXT NOT NULL,
            created_at TEXT NOT NULL,
            CHECK (kind IN ('export_snapshot', 'corpus_manifest', 'future_corpus_candidate')),
            CHECK (state IN ('active', 'revocation_pending', 'revoked', 'expired')),
            CHECK (generation >= 0)
        );
CREATE TABLE semantic_governed_artifact_auth_nonces (
            tenant_id TEXT NOT NULL,
            consumer_id TEXT NOT NULL,
            nonce TEXT NOT NULL,
            used_at TEXT NOT NULL,
            PRIMARY KEY (tenant_id, consumer_id, nonce)
        );
CREATE TABLE semantic_governed_artifact_consumers (
            tenant_id TEXT NOT NULL,
            consumer_id TEXT NOT NULL,
            consumer_key_id TEXT NOT NULL,
            consumer_public_key TEXT NOT NULL,
            created_at TEXT NOT NULL,
            PRIMARY KEY (tenant_id, consumer_id, consumer_key_id)
        );
CREATE TABLE semantic_validation_reports (
            report_id TEXT PRIMARY KEY,
            tenant_id TEXT NOT NULL,
            report_version INTEGER NOT NULL,
            assertion_ids TEXT NOT NULL,
            shape_set_id TEXT NOT NULL,
            shape_set_version TEXT NOT NULL,
            validation_profile_id TEXT NOT NULL,
            validation_profile_version TEXT NOT NULL,
            checkpoint_generation INTEGER,
            run_id TEXT NOT NULL,
            state TEXT NOT NULL,
            action TEXT NOT NULL,
            source TEXT NOT NULL,
            evaluated_at TEXT NOT NULL,
            report_mapping TEXT NOT NULL,
            CHECK (report_version = 1),
            CHECK (checkpoint_generation IS NULL OR checkpoint_generation >= 0),
            CHECK (state IN ('conforms', 'nonconformant', 'incomplete')),
            CHECK (action IN ('accept', 'accept-with-report', 'reject', 'quarantine')),
            CHECK (source IN ('asserted', 'imported', 'inferred', 'revalidation'))
        );
CREATE TABLE semantic_validation_results (
            tenant_id TEXT NOT NULL,
            report_id TEXT NOT NULL,
            ordinal INTEGER NOT NULL,
            assertion_id TEXT,
            shape_id TEXT,
            constraint_code TEXT NOT NULL,
            severity TEXT NOT NULL,
            PRIMARY KEY (tenant_id, report_id, ordinal),
            CHECK (ordinal >= 0),
            CHECK (severity IN ('info', 'warning', 'violation'))
        );
CREATE TABLE semantic_validation_report_assertions (
            tenant_id TEXT NOT NULL,
            report_id TEXT NOT NULL,
            assertion_id TEXT NOT NULL,
            PRIMARY KEY (tenant_id, report_id, assertion_id)
        );
CREATE TABLE semantic_validation_report_revisions (
            tenant_id TEXT NOT NULL,
            report_id TEXT NOT NULL,
            assertion_id TEXT NOT NULL,
            revision_id TEXT NOT NULL,
            PRIMARY KEY (tenant_id, report_id, assertion_id, revision_id)
        );
CREATE TABLE semantic_maintenance_state (
            tenant_id TEXT PRIMARY KEY,
            profile_key TEXT NOT NULL,
            checkpoint_generation INTEGER NOT NULL,
            checkpoint_event_id TEXT,
            run_id TEXT NOT NULL,
            status TEXT NOT NULL,
            capability_versions TEXT NOT NULL,
            repair_cursor_revision_id TEXT,
            repair_active INTEGER NOT NULL DEFAULT 0,
            repair_mode TEXT,
            repair_scan_complete INTEGER NOT NULL DEFAULT 0,
            repair_checkpoint_generation INTEGER,
            repair_checkpoint_event_id TEXT,
            repair_reconcile_cursor_derivation_id TEXT,
            audit_assertion_id TEXT,
            audit_assertion_revision_id TEXT,
            audit_competitor_cursor_revision_id TEXT,
            updated_at TEXT NOT NULL,
            CHECK (checkpoint_generation >= 0),
            CHECK (repair_active IN (0, 1)),
            CHECK (repair_scan_complete IN (0, 1)),
            CHECK (repair_mode IS NULL OR repair_mode IN ('full_rebuild', 'profile_change', 'current_scan')),
            CHECK (status IN ('complete', 'partial', 'failed', 'no_op'))
        );
CREATE TABLE semantic_maintenance_runs (
            tenant_id TEXT NOT NULL,
            run_id TEXT NOT NULL,
            profile_key TEXT NOT NULL,
            source_generation INTEGER NOT NULL,
            status TEXT NOT NULL,
            reason TEXT,
            result_mapping TEXT NOT NULL,
            started_at TEXT NOT NULL,
            completed_at TEXT,
            PRIMARY KEY (tenant_id, run_id),
            CHECK (source_generation >= 0),
            CHECK (status IN ('running', 'complete', 'partial', 'failed', 'no_op'))
        );
CREATE TABLE semantic_maintenance_leases (
            tenant_id TEXT PRIMARY KEY,
            holder_id TEXT NOT NULL,
            fencing_token INTEGER NOT NULL,
            expires_at DOUBLE PRECISION NOT NULL,
            updated_at TEXT NOT NULL,
            CHECK (fencing_token > 0)
        );
CREATE TABLE semantic_maintenance_reports (
            tenant_id TEXT NOT NULL,
            report_id TEXT NOT NULL,
            report_kind TEXT NOT NULL,
            evidence_digest TEXT NOT NULL,
            status TEXT NOT NULL,
            evidence_mapping TEXT NOT NULL,
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL,
            PRIMARY KEY (tenant_id, report_id),
            UNIQUE (tenant_id, evidence_digest),
            CHECK (report_kind IN ('contradiction_candidate', 'supersession_candidate', 'orphan_provenance', 'expired_assertion', 'ineligible_assertion')),
            CHECK (status IN ('review_required', 'deterministic_action_applied'))
        );
CREATE TABLE legacy_fact_migration_records (tenant_id TEXT NOT NULL, node_id TEXT NOT NULL, content_hash TEXT NOT NULL, source_occurrence_id TEXT, assertion_id TEXT, revision_id TEXT, outcome TEXT NOT NULL, created_at TIMESTAMP NOT NULL, PRIMARY KEY (tenant_id, node_id));
CREATE TABLE legacy_fact_migration_checkpoints (tenant_id TEXT NOT NULL, migration_name TEXT NOT NULL, last_node_id TEXT, state TEXT NOT NULL, updated_at TIMESTAMP NOT NULL, PRIMARY KEY (tenant_id, migration_name));
CREATE TABLE legacy_fact_migration_invalidations (tenant_id TEXT NOT NULL, migration_name TEXT NOT NULL, assertion_id TEXT NOT NULL, state TEXT NOT NULL, generation INTEGER NOT NULL DEFAULT 1, created_at TIMESTAMP NOT NULL, delivered_at TIMESTAMP, PRIMARY KEY (tenant_id, migration_name, assertion_id));
CREATE TABLE wait_signal_rekeys (
    id TEXT PRIMARY KEY,
    agent_id TEXT NOT NULL DEFAULT '',
    kind TEXT NOT NULL,
    handle TEXT NOT NULL,
    previous_token TEXT NOT NULL,
    token TEXT NOT NULL,
    reason TEXT NOT NULL,
    recorded_at TIMESTAMP NOT NULL
);
CREATE TABLE embedding_profiles (
                    id          TEXT PRIMARY KEY,
                    provider    TEXT NOT NULL,
                    model       TEXT NOT NULL,
                    dim         INTEGER NOT NULL,
                    space_id    TEXT NOT NULL,
                    normalized  INTEGER NOT NULL DEFAULT 0,
                    created_at  TEXT DEFAULT CURRENT_TIMESTAMP
                , parity_cosine REAL);
CREATE TABLE conversation_history_undated (
    message_id INTEGER PRIMARY KEY,
    agent_id TEXT NOT NULL,
    original_created_at TEXT,
    derived_created_at TIMESTAMP NOT NULL,
    derived_from TEXT NOT NULL,
    recorded_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE conversation_sessions (
    agent_id              TEXT NOT NULL,
    session_id            TEXT NOT NULL,
    started_at            TIMESTAMP NOT NULL,
    last_message_at       TIMESTAMP NOT NULL,
    message_count         INTEGER NOT NULL DEFAULT 0,
    user_message_count    INTEGER NOT NULL DEFAULT 0,
    first_user_message_id INTEGER,
    wake_source           TEXT,
    PRIMARY KEY (agent_id, session_id)
);
CREATE TABLE conversation_session_watermarks (
    agent_id             TEXT PRIMARY KEY,
    accounted_epoch      TEXT NOT NULL DEFAULT '',
    accounted_revision   BIGINT NOT NULL DEFAULT 0,
    accounted_generation TEXT NOT NULL DEFAULT '',
    accounted_valid   INTEGER NOT NULL DEFAULT 0,
    accounted_stamp   BIGINT NOT NULL DEFAULT 0,
    accounted_appends BIGINT NOT NULL DEFAULT 0,
    accounted_through BIGINT NOT NULL DEFAULT 0,
    accounted_target  BIGINT NOT NULL DEFAULT 0
);
CREATE TABLE conversation_history_changes (
    agent_id   TEXT NOT NULL,
    slot       BIGINT NOT NULL DEFAULT 0,
    changes    BIGINT NOT NULL DEFAULT 0,
    appends    BIGINT NOT NULL DEFAULT 0,
    generation TEXT NOT NULL DEFAULT '',
    PRIMARY KEY (agent_id, slot)
);
CREATE TABLE constitution_runtime_state (
                agent_id TEXT PRIMARY KEY,
                safe_mode INTEGER NOT NULL,
                safe_mode_reason TEXT,
                safe_mode_entered_at TEXT,
                safe_mode_exited_at TEXT,
                safe_mode_exit_authorization TEXT,
                last_successful_audit_at TEXT,
                interaction_count INTEGER NOT NULL DEFAULT 0
                    CHECK (interaction_count >= 0),
                bootstrap_pending INTEGER NOT NULL,
                schema_version INTEGER NOT NULL,
                updated_at TEXT NOT NULL,
                safe_mode_cause TEXT,
                revision INTEGER NOT NULL DEFAULT 0 CHECK (revision >= 0),
                generation TEXT NOT NULL DEFAULT ''
            );
CREATE TABLE constitution_runtime_events (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                agent_id TEXT NOT NULL,
                event_type TEXT NOT NULL,
                reason TEXT,
                authorization_detail TEXT,
                occurred_at TEXT NOT NULL
            );
CREATE TABLE a2a_outbound_dispatches (
                dispatch_id TEXT NOT NULL,
                sender_id TEXT NOT NULL,
                sender_tenant TEXT NOT NULL,
                recipient_id TEXT NOT NULL,
                tenant TEXT NOT NULL,
                signing_did TEXT NOT NULL,
                interface_url TEXT NOT NULL,
                protocol_binding TEXT NOT NULL,
                message_id TEXT NOT NULL,
                requested_context_id TEXT NOT NULL,
                request_digest TEXT NOT NULL,
                message_digest TEXT NOT NULL,
                dispatch_tool TEXT NOT NULL,
                verb TEXT NOT NULL,
                created_at TEXT NOT NULL,
                state TEXT NOT NULL CHECK (state IN ('reserved', 'submitting', 'unknown', 'not-sent', 'acknowledged', 'complete')),
                revision BIGINT NOT NULL CHECK (revision >= 0),
                remote_task_id TEXT,
                remote_context_id TEXT,
                remote_task_state TEXT,
                response_digest TEXT,
                response_kind TEXT,
                updated_at TEXT NOT NULL,
                operation_id TEXT NOT NULL,
                cancel_operation_id TEXT,
                cancel_request_digest TEXT,
                cancel_state TEXT CHECK (cancel_state IN ('reserved', 'submitting', 'unknown', 'not-sent', 'acknowledged', 'complete')),
                root_dispatch_id TEXT NOT NULL,
                parent_dispatch_id TEXT,
                PRIMARY KEY (sender_id, sender_tenant, dispatch_id),
                UNIQUE (sender_id, sender_tenant, message_id),
                FOREIGN KEY (sender_id, sender_tenant, root_dispatch_id)
                    REFERENCES a2a_outbound_dispatches (sender_id, sender_tenant, dispatch_id),
                FOREIGN KEY (sender_id, sender_tenant, parent_dispatch_id)
                    REFERENCES a2a_outbound_dispatches (sender_id, sender_tenant, dispatch_id)
            );
CREATE TABLE a2a_native_questions (
                sender_id TEXT NOT NULL, sender_tenant TEXT NOT NULL,
                question_id TEXT NOT NULL, dispatch_id TEXT NOT NULL,
                recipient_id TEXT NOT NULL, recipient_tenant TEXT NOT NULL,
                original_question TEXT NOT NULL, request_json TEXT NOT NULL,
                origin_turn_id TEXT NOT NULL,
                origin_session_id TEXT NOT NULL, causation_json TEXT NOT NULL,
                deadline TEXT NOT NULL,
                status TEXT NOT NULL CHECK (status IN ('WAITING', 'RESOLVED', 'EXPIRED')),
                receiver_settled INTEGER NOT NULL CHECK (receiver_settled IN (0,1)),
                response_json TEXT, response_digest TEXT,
                PRIMARY KEY (sender_id, sender_tenant, question_id),
                UNIQUE (sender_id, sender_tenant, dispatch_id)
            );
CREATE TABLE a2a_native_question_wakes (
                sender_id TEXT NOT NULL, sender_tenant TEXT NOT NULL,
                question_id TEXT NOT NULL, wave TEXT NOT NULL
                    CHECK (wave IN ('answer','deadline','late-answer')),
                event_id TEXT NOT NULL, payload_json TEXT NOT NULL,
                claim_token TEXT, lease_until TEXT, handed_off_at TEXT, delivery_failed_at TEXT,
                PRIMARY KEY (sender_id, sender_tenant, question_id, wave),
                UNIQUE (sender_id, sender_tenant, event_id)
            );
CREATE TABLE a2a_tasks (
                id TEXT PRIMARY KEY,
                session_id TEXT,
                user_id TEXT,
                task_type TEXT NOT NULL,
                status TEXT DEFAULT 'submitted',
                message TEXT,
                artifacts TEXT DEFAULT '[]',
                history TEXT DEFAULT '[]',
                metadata TEXT DEFAULT '{}',
                created_at TEXT DEFAULT (datetime('now')),
                updated_at TEXT DEFAULT (datetime('now')),
                creator_agent_id TEXT,
                recipient_agent_id TEXT,
                canceled_by TEXT,
                cancel_reason TEXT,
                cancel_previous_status TEXT,
                cancel_operation_id TEXT,
                terminal_operation_id TEXT,
                lifecycle_revision BIGINT NOT NULL DEFAULT 0,
                lifecycle_updated_at TEXT,
                status_timestamp_seconds BIGINT,
                status_timestamp_nanos INTEGER,
                tenant TEXT NOT NULL DEFAULT '',
                cognition_wake_eligible INTEGER NOT NULL DEFAULT 1 CHECK (cognition_wake_eligible IN (0,1)),
                input_revision BIGINT NOT NULL DEFAULT 0 CHECK (input_revision >= 0),
                input_wake_eligible INTEGER NOT NULL DEFAULT 1 CHECK (input_wake_eligible IN (0,1))
            );
CREATE TABLE a2a_task_inputs (
                task_id TEXT NOT NULL REFERENCES a2a_tasks(id) ON DELETE CASCADE,
                input_revision BIGINT NOT NULL CHECK (input_revision >= 0),
                message_id TEXT NOT NULL, request_json TEXT NOT NULL, request_digest TEXT NOT NULL,
                wire_request_digest TEXT NOT NULL CHECK (length(wire_request_digest) = 64),
                PRIMARY KEY (task_id, input_revision), UNIQUE (task_id, message_id)
            );
CREATE TABLE a2a_task_changes (
                    sequence INTEGER PRIMARY KEY AUTOINCREMENT,
                    recipient_id TEXT NOT NULL,
                    tenant TEXT NOT NULL,
                    task_id TEXT NOT NULL REFERENCES a2a_tasks(id) ON DELETE CASCADE,
                    forwarded_event_id TEXT
                );
CREATE TABLE a2a_protocol_schema (
                singleton INTEGER PRIMARY KEY CHECK (singleton = 1),
                revision INTEGER NOT NULL CHECK (revision = 1)
            );
CREATE TABLE a2a_contexts (
                context_id TEXT NOT NULL,
                tenant TEXT NOT NULL,
                recipient_agent_id TEXT NOT NULL,
                creator_agent_id TEXT NOT NULL,
                created_at TEXT DEFAULT (datetime('now')),
                PRIMARY KEY (recipient_agent_id, tenant, context_id)
            );
CREATE TABLE a2a_sessions (
                id TEXT PRIMARY KEY,
                agent_name TEXT NOT NULL,
                user_id TEXT,
                state TEXT DEFAULT '{}',
                events TEXT DEFAULT '[]',
                metadata TEXT DEFAULT '{}',
                created_at TEXT DEFAULT (datetime('now')),
                updated_at TEXT DEFAULT (datetime('now'))
            );
CREATE TABLE a2a_observability (
                id TEXT PRIMARY KEY,
                timestamp TEXT DEFAULT (datetime('now')),
                agent_name TEXT NOT NULL,
                session_id TEXT,
                event_type TEXT NOT NULL,
                tool_name TEXT,
                duration_ms INTEGER,
                success INTEGER DEFAULT 1,
                error_message TEXT,
                metadata TEXT DEFAULT '{}'
            );
CREATE TABLE a2a_llm_calls (
                id TEXT PRIMARY KEY,
                timestamp TEXT DEFAULT (datetime('now')),
                agent_did TEXT,
                session_id TEXT,
                companion_id TEXT,
                user_id TEXT,
                provider TEXT NOT NULL,
                model TEXT NOT NULL,
                system_prompt_preview TEXT,
                user_prompt_preview TEXT,
                response_preview TEXT,
                input_tokens INTEGER,
                output_tokens INTEGER,
                duration_ms INTEGER NOT NULL,
                success INTEGER DEFAULT 1,
                error_message TEXT,
                tool_calls TEXT,
                metadata TEXT DEFAULT '{}'
            );
CREATE TABLE a2a_tool_dispatches (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                agent_did TEXT NOT NULL,
                session_id TEXT,
                turn_id TEXT NOT NULL,
                ts TEXT DEFAULT (datetime('now')),
                tool_name TEXT NOT NULL,
                adapter TEXT NOT NULL,
                args_redacted TEXT NOT NULL,
                result_status TEXT NOT NULL CHECK (
                    result_status IN ('success', 'error', 'empty', 'policy_denied', 'timeout')
                ),
                error_class TEXT,
                error_message TEXT,
                latency_ms INTEGER NOT NULL,
                result_size_bytes INTEGER
            );
CREATE TABLE a2a_native_store_schema (
                component TEXT PRIMARY KEY,
                revision INTEGER NOT NULL CHECK (revision > 0)
            );
CREATE TABLE a2a_memory (
                id TEXT PRIMARY KEY,
                session_id TEXT,
                content TEXT,
                tags TEXT DEFAULT '[]',
                metadata TEXT DEFAULT '{}',
                created_at TEXT DEFAULT (datetime('now'))
            );
CREATE VIRTUAL TABLE a2a_memory_fts
            USING fts5(
                content,
                content='a2a_memory',
                content_rowid='rowid'
            );
CREATE TABLE a2a_feedback (
                id TEXT PRIMARY KEY,
                agent_name TEXT NOT NULL,
                session_id TEXT,
                source TEXT NOT NULL,
                category TEXT NOT NULL,
                severity TEXT NOT NULL,
                status TEXT DEFAULT 'open',
                title TEXT NOT NULL,
                description TEXT NOT NULL,
                context TEXT DEFAULT '{}',
                resolution TEXT,
                created_at TEXT DEFAULT (datetime('now')),
                updated_at TEXT DEFAULT (datetime('now')),
                resolved_at TEXT,
                metadata TEXT DEFAULT '{}'
            );
CREATE TABLE feature_enablement (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                agent_did TEXT NOT NULL,
                kind TEXT NOT NULL CHECK (kind IN ('feature', 'mcp_server')),
                name TEXT NOT NULL,
                state TEXT NOT NULL CHECK (state IN ('enabled', 'disabled')),
                actor TEXT,
                metadata TEXT,
                updated_at TEXT DEFAULT (datetime('now')),
                UNIQUE(agent_did, kind, name)
            );
CREATE TABLE signal_log (
                id TEXT PRIMARY KEY,
                source TEXT NOT NULL,
                kind TEXT NOT NULL,
                mode TEXT NOT NULL,
                urgency TEXT NOT NULL,
                dedupe_key TEXT,
                target_agent TEXT NOT NULL,
                session_id TEXT,
                caller_redacted TEXT,
                visibility TEXT NOT NULL,
                dispatched_at TEXT DEFAULT (datetime('now')),
                completed_at TEXT,
                status TEXT NOT NULL,
                duration_ms INTEGER NOT NULL,
                turn_id TEXT,
                artifact_digest TEXT,
                action_result_digest TEXT,
                payload_digest TEXT NOT NULL,
                payload_redacted TEXT,
                payload_raw TEXT,
                result_summary TEXT,
                causation_chain_digest TEXT NOT NULL,
                error TEXT,
                retention_until TEXT NOT NULL
            , constitution_hash TEXT, doctrine_bundle_hash TEXT, echo_canary_status TEXT, injected_clauses_json TEXT, dropped_clauses_json TEXT, prompt_template_hash TEXT);
CREATE TABLE durable_signal_events (
                event_id TEXT PRIMARY KEY,
                source_event_id TEXT,
                agent_id TEXT NOT NULL,
                target_agent TEXT NOT NULL,
                source TEXT NOT NULL,
                kind TEXT NOT NULL,
                mode TEXT NOT NULL,
                payload TEXT NOT NULL,
                session_id TEXT,
                caller_identity TEXT,
                visibility TEXT NOT NULL,
                urgency TEXT NOT NULL,
                dedupe_key TEXT,
                causation_chain TEXT NOT NULL,
                arrived_at TEXT NOT NULL,
                committed_at TEXT DEFAULT (datetime('now')),
                retention_until TEXT NOT NULL,
                source_sequence BIGINT NOT NULL,
                UNIQUE (agent_id, source, source_event_id)
            );
CREATE TABLE durable_signal_source_sequences (
                agent_id TEXT NOT NULL,
                source TEXT NOT NULL,
                current_sequence BIGINT NOT NULL,
                PRIMARY KEY (agent_id, source),
                CHECK (current_sequence >= 0)
            );
CREATE TABLE durable_signal_source_sequence_recovery (
                agent_id TEXT NOT NULL,
                source TEXT NOT NULL,
                recovery_sequence BIGINT NOT NULL,
                PRIMARY KEY (agent_id, source),
                CHECK (recovery_sequence >= 0)
            );
CREATE TABLE durable_signal_source_sequence_high_water (
                agent_id TEXT NOT NULL,
                source TEXT NOT NULL,
                high_water_sequence BIGINT NOT NULL,
                PRIMARY KEY (agent_id, source),
                CHECK (high_water_sequence >= 0)
            );
CREATE TABLE durable_signal_source_sequence_seen (
                agent_id TEXT NOT NULL,
                source TEXT NOT NULL,
                PRIMARY KEY (agent_id, source)
            );
CREATE TABLE durable_signal_source_sequence_state (
                singleton INTEGER PRIMARY KEY,
                counter_history_lost INTEGER NOT NULL,
                backfill_completed INTEGER
                    NOT NULL DEFAULT FALSE,
                scope_work_seeded INTEGER
                    NOT NULL DEFAULT FALSE,
                event_work_seeded INTEGER
                    NOT NULL DEFAULT FALSE,
                scope_validation_completed INTEGER
                    NOT NULL DEFAULT FALSE,
                scope_validation_after_agent_id TEXT,
                scope_validation_after_source TEXT,
                CHECK (singleton = 1)
            );
CREATE TABLE durable_signal_source_sequence_scope_work (
                agent_id TEXT NOT NULL,
                source TEXT NOT NULL,
                PRIMARY KEY (agent_id, source)
            );
CREATE TABLE durable_signal_source_sequence_event_work (
                agent_id TEXT NOT NULL,
                source TEXT NOT NULL,
                event_id TEXT NOT NULL,
                PRIMARY KEY (agent_id, source, event_id)
            );
CREATE TABLE durable_signal_consumers (
                agent_id TEXT NOT NULL,
                consumer_id TEXT NOT NULL,
                source TEXT NOT NULL,
                correlation_selector TEXT,
                max_attempts INTEGER NOT NULL,
                lease_seconds INTEGER NOT NULL,
                active INTEGER NOT NULL,
                replay_retained INTEGER NOT NULL DEFAULT 1,
                created_at TEXT DEFAULT (datetime('now')),
                updated_at TEXT DEFAULT (datetime('now')),
                PRIMARY KEY (agent_id, consumer_id)
            );
CREATE TABLE durable_signal_deliveries (
                delivery_id TEXT PRIMARY KEY,
                agent_id TEXT NOT NULL,
                consumer_id TEXT NOT NULL,
                event_id TEXT NOT NULL,
                status TEXT NOT NULL,
                attempts INTEGER NOT NULL DEFAULT 0,
                max_attempts INTEGER NOT NULL,
                lease_owner TEXT,
                lease_token TEXT,
                lease_expires_at TEXT,
                next_attempt_at TEXT,
                last_error TEXT,
                acknowledged_at TEXT,
                terminal_at TEXT,
                created_at TEXT DEFAULT (datetime('now')),
                updated_at TEXT DEFAULT (datetime('now')),
                UNIQUE (agent_id, consumer_id, event_id),
                FOREIGN KEY (event_id) REFERENCES durable_signal_events(event_id)
                    ON DELETE CASCADE,
                FOREIGN KEY (agent_id, consumer_id)
                    REFERENCES durable_signal_consumers(agent_id, consumer_id)
                    ON DELETE RESTRICT
            );
CREATE TABLE durable_signal_runtime_owners (
                agent_id TEXT NOT NULL,
                owner_id TEXT NOT NULL,
                heartbeat_at TEXT NOT NULL,
                stopped_at TEXT,
                created_at TEXT DEFAULT (datetime('now')),
                updated_at TEXT DEFAULT (datetime('now')),
                PRIMARY KEY (agent_id, owner_id)
            );
CREATE TABLE durable_signal_event_integrity (
                event_id TEXT PRIMARY KEY,
                integrity_binding TEXT NOT NULL,
                FOREIGN KEY (event_id) REFERENCES durable_signal_events(event_id)
                    ON DELETE CASCADE
            );
CREATE TABLE durable_signal_ingress_receipts (
                event_id TEXT PRIMARY KEY,
                receipt_version INTEGER NOT NULL,
                receipt_id TEXT NOT NULL,
                agent_id TEXT NOT NULL,
                source TEXT NOT NULL,
                source_sequence BIGINT NOT NULL,
                policy_epoch TEXT NOT NULL,
                sanitized_at_ingress INTEGER NOT NULL,
                FOREIGN KEY (event_id) REFERENCES durable_signal_events(event_id)
                    ON DELETE CASCADE
            );
CREATE TABLE security_permissions (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    feature_name TEXT NOT NULL,
                    tool_name TEXT NOT NULL,
                    level TEXT NOT NULL DEFAULT 'ask',
                    reason TEXT,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    UNIQUE(feature_name, tool_name)
                );
CREATE TABLE security_dispatch_entries (
                    tool_name TEXT PRIMARY KEY,
                    first_seen_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE security_global_settings (
                    key TEXT PRIMARY KEY,
                    value TEXT NOT NULL,
                    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE security_audit_log (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    feature_name TEXT,
                    tool_name TEXT,
                    action TEXT,
                    decision TEXT,
                    user_choice TEXT,
                    args_summary TEXT,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE auto_approve_rules (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    agent TEXT,
                    pattern TEXT NOT NULL,
                    repo_scope TEXT NOT NULL DEFAULT '',
                    added_by TEXT,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    UNIQUE(agent, pattern, repo_scope)
                );
CREATE TABLE auto_approve_audit (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    agent_did TEXT,
                    agent_name TEXT,
                    feature_name TEXT,
                    tool_name TEXT,
                    command TEXT,
                    pattern TEXT,
                    repo_scope TEXT,
                    rule_source TEXT,
                    decision TEXT NOT NULL DEFAULT 'auto_approved',
                    exit_code INTEGER,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    completed_at TIMESTAMP
                );
CREATE INDEX idx_file_owners_agent
    ON file_owners(agent_id, content_hash);
CREATE INDEX idx_graph_nodes_type ON graph_nodes(node_type);
CREATE INDEX idx_graph_nodes_type_label ON graph_nodes(node_type, label);
CREATE INDEX idx_graph_edges_target ON graph_edges(target_id, label);
CREATE INDEX idx_graph_edges_label ON graph_edges(label);
CREATE INDEX idx_graph_node_owners_agent
    ON graph_node_owners(agent_id, node_id);
CREATE INDEX idx_graph_edge_owners_agent
    ON graph_edge_owners(agent_id, source_id, target_id, label);
CREATE INDEX idx_document_chunk_owners_agent
    ON document_chunk_owners(agent_id, chunk_id);
CREATE INDEX idx_conversation_lexical_token_lookup
    ON conversation_lexical_tokens(agent_id, token_hash);
CREATE INDEX idx_conversation_agent_id ON conversation_history(agent_id);
CREATE INDEX idx_conversation_agent_created_at
    ON conversation_history(agent_id, created_at DESC);
CREATE INDEX idx_conversation_titles_agent
    ON conversation_titles(agent_id);
CREATE INDEX idx_temporal_patterns_agent ON temporal_patterns(agent_id);
CREATE INDEX idx_memory_episodes_agent ON memory_episodes(agent_id);
CREATE INDEX idx_reflection_insights_agent ON reflection_insights(agent_id);
CREATE INDEX idx_reflection_insights_session ON reflection_insights(session_id);
CREATE INDEX idx_reflection_sessions_agent ON reflection_sessions(agent_id);
CREATE INDEX idx_improvement_proposals_agent ON improvement_proposals(agent_id);
CREATE INDEX idx_behavior_rules_agent ON behavior_rules(agent_id);
CREATE INDEX idx_behavior_rules_active ON behavior_rules(agent_id, active);
CREATE INDEX idx_user_service_keys_user ON user_service_keys(user_id);
CREATE INDEX idx_user_service_keys_provider ON user_service_keys(provider_id);
CREATE INDEX idx_agent_service_keys_agent ON agent_service_keys(agent_did);
CREATE INDEX idx_agent_service_keys_provider ON agent_service_keys(provider_id);
CREATE INDEX idx_user_byok_keys_agent ON user_byok_service_keys(agent_did);
CREATE INDEX idx_user_byok_keys_provider ON user_byok_service_keys(provider_id);
CREATE INDEX idx_host_service_keys_provider ON host_service_keys(provider_id);
CREATE INDEX idx_user_master_keys_did ON user_master_service_keys(master_did);
CREATE INDEX idx_user_master_keys_provider ON user_master_service_keys(provider_id);
CREATE INDEX idx_sponsor_master_keys_did ON sponsor_master_service_keys(master_did);
CREATE INDEX idx_sponsor_master_keys_provider ON sponsor_master_service_keys(provider_id);
CREATE INDEX idx_sponsor_beneficiaries_sponsor ON sponsor_beneficiaries(sponsor_did);
CREATE INDEX idx_service_key_usage_key ON service_key_usage(key_id);
CREATE INDEX idx_service_key_usage_recorded ON service_key_usage(recorded_at);
