CREATE TRIGGER conversation_history_change_insert_91eeb0e7 AFTER INSERT ON conversation_history FOR EACH ROW BEGIN INSERT INTO conversation_history_changes (agent_id, slot, changes, appends, generation) VALUES (NEW.agent_id, 0, 0, 0, hex(randomblob(16))) ON CONFLICT (agent_id, slot) DO NOTHING; INSERT INTO conversation_history_changes (agent_id, slot, changes, appends) VALUES (NEW.agent_id, 0, 1, 1) ON CONFLICT (agent_id, slot) DO UPDATE SET changes = conversation_history_changes.changes + 1, appends = conversation_history_changes.appends + 1; END;
CREATE TRIGGER conversation_history_change_update_91eeb0e7 AFTER UPDATE ON conversation_history FOR EACH ROW WHEN (OLD.id IS NOT NEW.id OR OLD.agent_id IS NOT NEW.agent_id OR OLD.session_id IS NOT NEW.session_id OR OLD.role IS NOT NEW.role OR CASE WHEN json_valid(OLD.metadata) = 1 THEN CASE WHEN (SELECT COUNT(*) - COUNT(DISTINCT key) FROM json_each(OLD.metadata) WHERE key IN ('session_id', 'new_session', 'operator_signal', 'signal_wake')) = 0 THEN json_extract(OLD.metadata, '$."session_id"', '$."new_session"', '$."operator_signal"', '$."signal_wake"') ELSE OLD.metadata END ELSE OLD.metadata END IS NOT CASE WHEN json_valid(NEW.metadata) = 1 THEN CASE WHEN (SELECT COUNT(*) - COUNT(DISTINCT key) FROM json_each(NEW.metadata) WHERE key IN ('session_id', 'new_session', 'operator_signal', 'signal_wake')) = 0 THEN json_extract(NEW.metadata, '$."session_id"', '$."new_session"', '$."operator_signal"', '$."signal_wake"') ELSE NEW.metadata END ELSE NEW.metadata END OR OLD.created_at IS NOT NEW.created_at OR OLD.deleted_at IS NOT NEW.deleted_at OR OLD.archived_at IS NOT NEW.archived_at) BEGIN INSERT INTO conversation_history_changes (agent_id, slot, changes, appends, generation) VALUES (NEW.agent_id, 0, 0, 0, hex(randomblob(16))) ON CONFLICT (agent_id, slot) DO NOTHING; INSERT INTO conversation_history_changes (agent_id, slot, changes, appends) VALUES (NEW.agent_id, 0, 1, 0) ON CONFLICT (agent_id, slot) DO UPDATE SET changes = conversation_history_changes.changes + 1, appends = conversation_history_changes.appends + 0; INSERT INTO conversation_history_changes (agent_id, slot, changes, appends, generation) SELECT OLD.agent_id, 0, 0, 0, hex(randomblob(16))  WHERE OLD.agent_id IS NOT NEW.agent_id ON CONFLICT (agent_id, slot) DO NOTHING; INSERT INTO conversation_history_changes (agent_id, slot, changes, appends) SELECT OLD.agent_id, 0, 1, 0 WHERE OLD.agent_id IS NOT NEW.agent_id ON CONFLICT (agent_id, slot) DO UPDATE SET changes = conversation_history_changes.changes + 1; END;
CREATE TRIGGER conversation_history_change_delete_91eeb0e7 AFTER DELETE ON conversation_history FOR EACH ROW BEGIN INSERT INTO conversation_history_changes (agent_id, slot, changes, appends, generation) VALUES (OLD.agent_id, 0, 0, 0, hex(randomblob(16))) ON CONFLICT (agent_id, slot) DO NOTHING; INSERT INTO conversation_history_changes (agent_id, slot, changes, appends) VALUES (OLD.agent_id, 0, 1, 0) ON CONFLICT (agent_id, slot) DO UPDATE SET changes = conversation_history_changes.changes + 1, appends = conversation_history_changes.appends + 0; END;
CREATE TRIGGER constitution_runtime_revision_fence_v4
                    BEFORE UPDATE ON constitution_runtime_state
                    FOR EACH ROW WHEN NEW.revision <> OLD.revision + 1 OR NEW.generation <> OLD.generation
                    BEGIN
                        SELECT RAISE(ABORT, 'constitution runtime revision fence refused old writer');
                    END;
CREATE TRIGGER constitution_runtime_revision_fence_v4_insert
                    BEFORE INSERT ON constitution_runtime_state
                    FOR EACH ROW WHEN NEW.generation = ''
                    BEGIN
                        SELECT RAISE(ABORT, 'constitution runtime generation fence refused old writer');
                    END;
CREATE TRIGGER a2a_tasks_terminal_update_v5
            BEFORE UPDATE ON a2a_tasks
            FOR EACH ROW
            WHEN OLD.status IN ('completed', 'failed', 'canceled', 'rejected')
            BEGIN
                SELECT RAISE(ABORT, 'terminal A2A task cannot be replaced');
            END;
CREATE TRIGGER a2a_tasks_terminal_replace_v5
            BEFORE INSERT ON a2a_tasks
            FOR EACH ROW
            WHEN EXISTS (
                SELECT 1
                 FROM a2a_tasks
                 WHERE id = NEW.id
                   AND status IN ('completed', 'failed', 'canceled', 'rejected')
            )
            BEGIN
                -- IGNORE runs before SQLite's REPLACE conflict action deletes
                -- the occupied row. It therefore fences legacy INSERT OR
                -- REPLACE while allowing modern INSERT ... ON CONFLICT DO
                -- NOTHING to report its normal zero-row duplicate outcome.
                SELECT RAISE(IGNORE);
            END;
CREATE TRIGGER a2a_tasks_authority_insert_v5
            BEFORE INSERT ON a2a_tasks
            FOR EACH ROW
            WHEN NEW.creator_agent_id IS NULL
              OR NEW.recipient_agent_id IS NULL
            BEGIN
                SELECT RAISE(ABORT, 'A2A task requires durable authority');
            END;
CREATE TRIGGER a2a_tasks_live_authority_update_v5
            BEFORE UPDATE ON a2a_tasks
            FOR EACH ROW
            WHEN NEW.status IN ('submitted', 'working', 'input-required', 'auth-required')
              AND (NEW.creator_agent_id IS NULL
                   OR NEW.recipient_agent_id IS NULL)
            BEGIN
                SELECT RAISE(ABORT, 'live A2A task requires durable authority');
            END;
CREATE TRIGGER a2a_memory_ai AFTER INSERT ON a2a_memory BEGIN
                INSERT INTO a2a_memory_fts(rowid, content)
                VALUES (new.rowid, new.content);
            END;
CREATE TRIGGER a2a_memory_ad AFTER DELETE ON a2a_memory BEGIN
                INSERT INTO a2a_memory_fts(a2a_memory_fts, rowid, content)
                VALUES('delete', old.rowid, old.content);
            END;
CREATE TRIGGER a2a_memory_au AFTER UPDATE ON a2a_memory BEGIN
                INSERT INTO a2a_memory_fts(a2a_memory_fts, rowid, content)
                VALUES('delete', old.rowid, old.content);
                INSERT INTO a2a_memory_fts(rowid, content)
                VALUES (new.rowid, new.content);
            END;
CREATE TRIGGER durable_signal_source_sequences_recovery_fence_insert_check_b23be026
            BEFORE INSERT ON durable_signal_source_sequences
            BEGIN
                SELECT CASE
                    WHEN EXISTS (
                        SELECT 1
                        FROM durable_signal_source_sequence_seen
                        WHERE agent_id = NEW.agent_id AND source = NEW.source
                    ) AND MAX(COALESCE((
                        SELECT recovery_sequence
                        FROM durable_signal_source_sequence_recovery
                        WHERE agent_id = NEW.agent_id AND source = NEW.source
                    ), 0), COALESCE((
                        SELECT high_water_sequence
                        FROM durable_signal_source_sequence_high_water
                        WHERE agent_id = NEW.agent_id AND source = NEW.source
                    ), 0)) < 1
                    THEN RAISE(ABORT, 'both exact counter copies were lost for a previously seen scope or provide no positive high-water evidence')
                END;
            END;
CREATE TRIGGER durable_signal_source_sequences_recovery_fence_update_check_b23be026
            BEFORE UPDATE OF current_sequence ON durable_signal_source_sequences
            BEGIN
                SELECT CASE
                    WHEN EXISTS (
                        SELECT 1
                        FROM durable_signal_source_sequence_seen
                        WHERE agent_id = NEW.agent_id AND source = NEW.source
                    ) AND MAX(COALESCE((
                        SELECT recovery_sequence
                        FROM durable_signal_source_sequence_recovery
                        WHERE agent_id = NEW.agent_id AND source = NEW.source
                    ), 0), COALESCE((
                        SELECT high_water_sequence
                        FROM durable_signal_source_sequence_high_water
                        WHERE agent_id = NEW.agent_id AND source = NEW.source
                    ), 0)) < 1
                    THEN RAISE(ABORT, 'both exact counter copies were lost for a previously seen scope or provide no positive high-water evidence')
                END;
            END;
CREATE TRIGGER durable_signal_source_sequences_recovery_fence_insert_mirror_b23be026
            AFTER INSERT ON durable_signal_source_sequences
            BEGIN
                UPDATE durable_signal_source_sequences
                SET current_sequence = MAX(
                    current_sequence,
                    MAX(COALESCE((
                        SELECT recovery_sequence
                        FROM durable_signal_source_sequence_recovery
                        WHERE agent_id = NEW.agent_id AND source = NEW.source
                    ), 0), COALESCE((
                        SELECT high_water_sequence
                        FROM durable_signal_source_sequence_high_water
                        WHERE agent_id = NEW.agent_id AND source = NEW.source
                    ), 0))
                )
                WHERE agent_id = NEW.agent_id AND source = NEW.source;
                INSERT INTO durable_signal_source_sequence_recovery (
                    agent_id, source, recovery_sequence
                )
                SELECT agent_id, source, current_sequence
                FROM durable_signal_source_sequences
                WHERE agent_id = NEW.agent_id AND source = NEW.source
                ON CONFLICT (agent_id, source) DO UPDATE
                SET recovery_sequence = MAX(
                    durable_signal_source_sequence_recovery.recovery_sequence,
                    excluded.recovery_sequence
                );
                INSERT INTO durable_signal_source_sequence_high_water (
                    agent_id, source, high_water_sequence
                )
                SELECT agent_id, source, current_sequence
                FROM durable_signal_source_sequences
                WHERE agent_id = NEW.agent_id AND source = NEW.source
                ON CONFLICT (agent_id, source) DO UPDATE
                SET high_water_sequence = MAX(
                    durable_signal_source_sequence_high_water.high_water_sequence,
                    excluded.high_water_sequence
                );
                INSERT INTO durable_signal_source_sequence_seen (agent_id, source)
                SELECT agent_id, source
                FROM durable_signal_source_sequences
                WHERE agent_id = NEW.agent_id AND source = NEW.source
                  AND current_sequence > 0
                ON CONFLICT (agent_id, source) DO NOTHING;
            END;
CREATE TRIGGER durable_signal_source_sequences_recovery_fence_update_mirror_b23be026
            AFTER UPDATE OF current_sequence
            ON durable_signal_source_sequences
            BEGIN
                UPDATE durable_signal_source_sequences
